// Generated by qaia-playwright:automate — AC5 (sign-out and post-sign-out route refusal) and the
// AC1/AC4/AC5 smoke journey. Mobile = device emulation only (D100).
const { test, expect } = require('../fixtures');

const REFUSAL = (path) =>
  `Epic sadface: You can only access '/${path}' when you are logged in.`;

test('@QAIA-US-EVAL-013-010 @AC5 @P2 @state-transition — signing out from the drawer returns the shopper to the login page',
  async ({ signedIn, loginPage }) => {
    const { page, drawer } = signedIn;
    await drawer.open();
    await drawer.logoutLink.tap();
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(loginPage.loginButton).toBeVisible();
  });

test('@QAIA-US-EVAL-013-011 @AC5 @P1 @negative @state-transition — after signing out, requesting the catalogue URL directly is refused',
  async ({ signedIn, loginPage }) => {
    const { page, drawer } = signedIn;
    await drawer.open();
    await drawer.logoutLink.tap();
    await expect(page).toHaveURL('https://www.saucedemo.com/');

    await page.goto('/inventory.html');
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(loginPage.error).toHaveText(REFUSAL('inventory.html'));
  });

test('@QAIA-US-EVAL-013-012 @AC5 @P1 @negative @error-guessing — a shopper who never signed in cannot reach the catalogue URL',
  async ({ page, loginPage }) => {
    // No session fixture on purpose: this is the never-authenticated path, distinct from revocation.
    await page.goto('/inventory.html');
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(loginPage.error).toHaveText(REFUSAL('inventory.html'));
  });

for (const path of ['cart.html', 'checkout-step-one.html']) {
  test(`@QAIA-US-EVAL-013-013 @AC5 @P1 @negative @error-guessing — a shopper with no session cannot reach /${path} either`,
    async ({ page, loginPage }) => {
      await page.goto(`/${path}`);
      await expect(page).toHaveURL('https://www.saucedemo.com/');
      await expect(loginPage.error).toHaveText(REFUSAL(path));
    });
}

test('@QAIA-US-EVAL-013-017 @AC1 @AC4 @AC5 @P1 @use-case @smoke — a shopper browses, opens the full-screen drawer and signs out of a phone session',
  async ({ page, loginPage, inventoryPage, drawer }) => {
    // The only scenario that drives the sign-in FORM: here the form is part of the behaviour under
    // test (the journey), not an incidental precondition — everywhere else the session is seeded
    // declaratively by the `signedIn` fixture (atomic-preconditions rule).
    await loginPage.goto();
    await loginPage.signIn('standard_user', 'secret_sauce');
    await expect(inventoryPage.list).toBeVisible();

    await drawer.open();
    expect(await drawer.renderedWidth()).toBe(page.viewportSize().width);

    await drawer.logoutLink.tap();
    await expect(page).toHaveURL('https://www.saucedemo.com/');

    await page.goto('/inventory.html');
    await expect(loginPage.error).toHaveText(REFUSAL('inventory.html'));
  });
